struct Ref:H8SEmulator{void history(){lastread=lastwrite=-1;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0xc100&&a<0xc500)||(a>=0xcd60&&a<0xcd80)||(a>=0xfffd20&&a<0xfffd28)||(a>=0xffffc5&&a<0xffffcc)||(a>=0xffff7c&&a<0xffff7e)||(a>=0xfffe50&&a<0xfffe80)||(a>=0x600000&&a<0x600010)||(a>=0xc598&&a<0xc59a)||a==0xffffe8||a==0xbb0e||a==0xbb1c||a==0xbab0;}
struct RBus:H8SDevice{Ref&c;std::array<Event,16>e{};unsigned n=0,group=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=a==0x600004?uint8_t(group==1?16:7):c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
struct NBus:kstation::ControllerResourceBus{std::array<Event,16>e{};unsigned n=0,group=0;bool enabled=false;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=a==0x600004?uint8_t(group==1?16:7):state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
int main(int argc,char**argv){if(argc!=2)return 77;bool boot=false;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);if(!boot)d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xc100,0x400);c->memmap(&x,0xcd60,0x20);c->memmap(&x,0xfffd20,8);c->memmap(&x,0xffffc5,7);c->memmap(&x,0xffff7c,2);c->memmap(&x,0xffffe8,1);c->memmap(&x,0xbb0e,1);c->memmap(&x,0xfffe50,0x30);c->memmap(&x,0x600000,16);c->memmap(&x,0xc598,2);c->memmap(&x,0xbb1c,1);c->memmap(&x,0xbab0,1);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerDspTransferRuntime dsp;kstation::ControllerPeriodicUiRuntime rt;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!dsp.bindVerifiedFirmware(*d,rom.data(),rom.size())||!rt.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;y.enabled=true;for(unsigned a:{0x481au,0x496au,0x4062u,0x45aau}){c->memory[a]=0x54;c->memory[a+1]=0x70;}uint64_t graphs=0,phases=0,events=0,shorts=0;for(unsigned scenario=0;scenario<32;++scenario)for(unsigned flags=0;flags<256;++flags){rt.reset();irq.reset();dsp.reset();x.group=y.group=0;irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};for(unsigned i=0;i<0x400;++i)put(0xc100+i,uint8_t(i*31+flags));for(unsigned i=0;i<0x20;++i)put(0xcd60+i,0);for(unsigned i=0;i<8;++i)put(0xfffd20+i,0);uint16_t tick=uint16_t(flags*257),elapsed=uint16_t(scenario%2?25:24),last=uint16_t(tick-elapsed);put(0xfffd22,tick>>8);put(0xfffd23,tick);put(0xcd6a,last>>8);put(0xcd6b,last);put(0xc490,32);for(unsigned i=0;i<4;++i)put(0xc1c8+i,0);put(0xffffc7,uint8_t(flags));put(0xffffd3,0);put(0xffff7c,0);put(0xffff7d,scenario&2?8:0);put(0xcd7c,uint8_t(scenario%6));put(0xcd7f,uint8_t((scenario>>3)&1));put(0xbb0e,uint8_t((scenario>>4)&1));for(unsigned i=0;i<0x30;++i)put(0xfffe50+i,uint8_t((i*37+flags)|1));put(0xfffe66,0x12);put(0xfffe67,0x34);put(0xfffe68,0x56);put(0xfffe69,0x78);put(0xfffe70,uint8_t(scenario>>2&1));put(0xbb1c,uint8_t(scenario>>3&3));put(0xbab0,uint8_t(flags));put(0xc598,0xff);put(0xc599,0xff);uint32_t entry=0x3be4;c->pc=c->makepc(entry);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=((flags&0x81)==0x81)?1:0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history();d->lastRead=d->lastWrite=-1;if(!rt.start())return 3;for(unsigned k=0;rt.active();++k){if(k>50000){std::fprintf(stderr,"hang pc=%x scenario=%u flags=%u request=%u\n",c->getPC(),scenario,flags,unsigned(rt.request().service));return 4;}auto at=uint32_t(c->getPC());x.n=y.n=0;auto q=rt.request();if(q.service!=kstation::ControllerPeriodicUiRuntime::Service::None){using S=kstation::ControllerPeriodicUiRuntime::Service;if(q.service==S::Clock){if(!rt.beginClock(*d,dsp))return 23;continue;}using E=kstation::ControllerUiEncoderRouteRuntime::Service;unsigned target=q.service==S::Clock?0x1838:q.encoder.service==E::Edit?0x481a:q.encoder.service==E::Display?0x496a:q.encoder.service==E::ParameterControl?0x4062:0x45aa;if(at!=target){std::fprintf(stderr,"request pc=%x target=%x\n",at,target);return 20;}auto before=c->cycles;c->step();d->cycles+=c->cycles-before;d->lastRead=-1;if(!rt.completeService(q))return 21;continue;}auto cost=rt.nextClocks(*d,irq);if(!cost){std::fprintf(stderr,"cost pc=%x scenario=%u flags=%u\n",at,scenario,flags);return 5;}if(phases%31==0){auto before=d->cycles;for(unsigned b=0;b<cost;++b){auto r=rt.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}}c->step();auto r=rt.advanceBefore(*d,irq,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x scenario=%u flags=%u clocks=%llu/%llu io=%u/%u\n",at,scenario,flags,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i)if(x.e[i].at!=y.e[i].at||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x scenario=%u addr=%x/%x value=%x/%x time=%llu/%llu\n",at,scenario,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].at,y.e[i].at);return 8;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 9;if(std::memcmp(c->memory+0xc100,d->memory+0xc100,0x400)||std::memcmp(c->memory+0xcd60,d->memory+0xcd60,0x20))return 12;++graphs;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts);}
